if(a==='game-support'){const [runId,kind]=id.split('::'),run=state.gameSessions.find(s=>s.id===runId&&s.studentId===selectedId);G.support(run,kind);persist();render();return;}
if(a==='game-audio'){const run=state.gameSessions.find(s=>s.id===id&&s.studentId===selectedId),t=run?.items[run.index];if(!t||t.activity.readingTarget)throw Error('Preserve a leitura do alvo nesta tarefa.');speak(t.activity.audioRequired?t.activity.stimulusAudio:(t.activity.studentMaterial||'')+' '+t.activity.prompt,()=>{t.audioDelivered=true;persist();render();});return;}
if(a==='retry-list'){delete state.settings.retryFocus;persist();navigate('retries');return;}
if(a==='new-student'){studentForm();return;}
if(a==='edit-student'){studentForm(id);return;}
if(a==='select-student'){selectedId=id;state.settings.assessmentMode='tutor';persist();navigate('baseline');return;}
if(a==='demo'){
const existing=state.students.find(x=>x.demo);if(existing)selectedId=existing.id;else{const s={id:E.uid(),name:'Estudante demonstração',year:6,goal:'Experimentar a avaliação inicial e o ensino com apoio graduado.',access:'',demo:true,createdAt:new Date().toISOString()};state.students.push(s);selectedId=s.id;}persist('Perfil fictício criado. As respostas ainda precisam ser observadas.');navigate('baseline');return;
}
if(a==='close-dialog'){$('dialog').close();return;}
if(a==='baseline-slot'){baselineCursor=Number(id);activeBaseline().cursor=baselineCursor;persist();render();return;}
if(a==='next-baseline'){const base=activeBaseline();if(base.cursor+1<base.slots.length){base.cursor++;persist();navigate('baseline');}else finishBaseline();return;}
if(a==='finish-baseline'){finishBaseline();return;}
if(a==='confirm-finish-baseline'){
const base=activeBaseline();if(!base)return;A.complete(base);event('baseline_completed',{baselineId:base.id});persist('Avaliação guardada. O tutor vai analisar os registros.');$('dialog').close();navigate(state.settings.assessmentMode==='student'?'baseline':'progress');return;
}
if(a==='assessment-student'){captureDrafts();state.settings.assessmentMode='student';persist();render();return;}
if(a==='assessment-tutor'){captureDrafts();state.settings.assessmentMode='tutor';persist();render();return;}
if(a==='open-assessment-question'){const base=activeBaseline();base.cursor=Number(id);base.paused=false;state.settings.assessmentMode='student';persist();render();return;}
if(a==='pause-baseline'){if('speechSynthesis'in window)window.speechSynthesis.cancel();captureDrafts();const base=activeBaseline();if(!base)return;base.paused=true;persist('Pausa registrada. Você pode retomar do mesmo lugar.');render();return;}
if(a==='resume-baseline'){const base=activeBaseline();if(!base)return;if(base.paused)event('baseline_resumed',{baselineId:base.id});base.paused=false;persist();render();return;}
if(a==='skip-baseline'){const base=activeBaseline();if(!base)return;const form=b.closest('.task-card').querySelector('form');clearDraft(form);A.record(base,id,{notAssessed:true});if(base.cursor+1<base.slots.length)base.cursor++;persist('Questão guardada para outra hora.');render();if(base.responses.length===base.slots.length)finishBaseline();return;}
if(a==='confirm-observations'){const base=state.baselines.find(b=>b.id===id&&b.studentId===selectedId&&b.status==='completed');if(!base)throw Error('Conclua a aplicação antes de confirmar.');for(const r of base.responses.filter(r=>r.outcome==='pending'&&r.observationCode)){const obs=H.observation(r.observationCode);A.review(base,r.id,{...obs,educator:base.educator,note:'O adulto confirmou após a aplicação o registro por toque da ação observada.'});}persist('Observações confirmadas. Confira os próximos passos com o estudante.');render();return;}
if(a==='review-baseline'){reviewBaseline(id);return;}
if(a==='new-baseline-question'){activityForm(id,'baseline');return;}
if(a==='speak-baseline'){const base=activeBaseline(),slot=base.slots[base.cursor||0];if(slot.readingTarget||slot.activity.readingTarget||skill(slot.skillId)?.readingTarget){announce('A leitura do item altera a habilidade observada nesta sonda.',true);return;}if(slot.activity.audioRequired){speak(slot.activity.stimulusAudio,()=>{if(base.status==='active'&&!base.paused){slot.audioDelivered=true;slot.audioMode='speechSynthesis';persist();render();}});return;}speak((slot.activity.studentMaterial?slot.activity.studentMaterial+'\n':'')+slot.activity.prompt);return;}
if(a==='start-study'||a==='choose-study-first'){
if(activeSession())throw Error('Já existe uma sessão para retomar.');const p=lastPlan();if(!p)throw Error('Prepare e aprove o plano primeiro.');if(state.sessions.some(x=>x.planId===p.id))throw Error('Este plano já foi utilizado. Prepare o próximo com itens novos.');
state.sessions.push(E.startSession(p,a==='choose-study-first'?id:'',state));event('session_started',{planId:p.id});persist();navigate('study');return;
}
if(a==='pause-study'){if('speechSynthesis'in window)window.speechSynthesis.cancel();const session=activeSession();session.paused=true;event('session_paused',{sessionId:session.id});persist('Pausa registrada. Você pode retomar de onde parou.');render();return;}
if(a==='resume-study'){const session=activeSession();if(session.paused)event('session_resumed',{sessionId:session.id});session.paused=false;persist();render();return;}
if(a==='end-study'){endStudy();return;}
if(a==='confirm-end-study'){const session=activeSession();if(!session)return;state.sessions[state.sessions.findIndex(x=>x.id===session.id)]=E.finishSession(session);event('session_ended',{sessionId:session.id});persist('Sessão encerrada. O trabalho realizado está registrado.');$('dialog').close();navigate(currentArea==='student'?'student-progress':'progress');return;}
if(a==='observe-task'){const session=activeSession(),task=session.items[session.index];if(!['explain','model'].includes(task.phase))return;const field=$('learning-reflection'),note=field?.value?.trim();if(field?.form)clearDraft(field.form);if(note){session.reflections=session.reflections||[];session.reflections.push({taskId:task.id,note:note.slice(0,2000),at:new Date().toISOString()});}task.status='done';event('instruction_observed',{sessionId:session.id,taskId:task.id,phase:task.phase});if(session.index+1<session.items.length)session.index++;persist();navigate('study');return;}
if(a==='next-study'){const session=activeSession(),task=session.items[session.index];if(task.status!=='done')throw Error('Registre esta etapa antes de continuar.');if(session.index+1<session.items.length){session.index++;persist();navigate('study');}else endStudy();return;}
if(a==='speak-task'){const session=activeSession(),task=session.items[session.index];if(task.readingTarget&&!['explain','model'].includes(task.phase))throw Error('A leitura do item altera a habilidade observada. Combine a condição de acesso com o educador.');if(task.activity?.audioRequired){speak(task.activity.stimulusAudio,()=>{if(session.status==='active'&&!session.paused){task.audioDelivered=true;task.audioMode='speechSynthesis';persist();render();}});return;}speak(['explain','model'].includes(task.phase)?task.content:(task.activity.studentMaterial?task.activity.studentMaterial+'\n':'')+task.activity.prompt);return;}
if(a==='help-task'||a==='eliminate-task'||a==='explain-task'){
const session=activeSession();if(!session||session.paused)throw Error('Retome a sessão para pedir apoio.');const task=session.items[session.index];if(task.status==='done'||!task.activity)return;const helps=state.helpEvents.filter(x=>x.sessionId===session.id&&x.taskId===task.id),tips=helps.filter(x=>x.kind==='tip'||!x.kind),messages=task.activity.hints?.length?task.activity.hints:['Olhe o que a atividade pede. Vamos fazer uma parte de cada vez.','Compare cada opção com o que foi apresentado.'];let message,optionIndex;
if(a==='explain-task'){if(helps.some(h=>h.kind==='explain'))throw Error('A explicação já está disponível nesta tarefa.');message=(task.content+'\nExemplo de ensino: '+task.model).slice(0,12000);}else if(a==='eliminate-task'){if(task.activity.type!=='choice')throw Error('Esta atividade não tem alternativas.');optionIndex=H.nextElimination(task.activity.options,task.activity.answer,helps);message='Uma alternativa foi retirada com apoio.';}else{if(tips.length>=messages.length){announce('As dicas previstas já foram apresentadas. Você pode conversar com o tutor ou fazer uma pausa.');return;}message=messages[tips.length];}
state.helpEvents.push({id:E.uid(),sessionId:session.id,studentId:selectedId,taskId:task.id,skillId:task.skillId,kind:a==='eliminate-task'?'eliminate':a==='explain-task'?'explain':'tip',optionIndex,level:helps.length+1,message,at:new Date().toISOString(),scriptVersion:2});event('help_requested',{sessionId:session.id,taskId:task.id});persist();render();return;
}
if(a==='skill-detail'){skillDetail(id);return;}
if(a==='new-skill'){skillForm();return;}
if(a==='edit-skill'){skillForm(id);return;}
if(a==='add-activity'){activityForm(id);return;}
