$('import-file').addEventListener('change',async e=>{
const file=e.target.files[0];if(!file)return;
try{if(file.size>20*1024*1024)throw Error('Escolha um arquivo JSON de até 20 MB.');const data=JSON.parse(await file.text());if(importKind==='backup'){const valid=E.validateBackup(data,window.TRILUME_CATALOG);pendingImport={kind:'backup',value:valid};openDialog('Conferir importação de backup',`<p>O arquivo contém ${valid.students.length} estudante(s), ${valid.baselines.length} avaliação(ões) e ${valid.sessions.length} sessão(ões).</p><p>A importação substituirá os registros locais deste navegador. Uma cópia anterior será guardada localmente antes da troca.</p><div class="actions">${button('Cancelar','close-dialog','secondary')}${button('Importar e substituir registros locais','confirm-import')}</div>`);}else{
if(data.schemaVersion!==1||!Array.isArray(data.skills)||data.skills.length>10000)throw Error('Formato de biblioteca incompatível. Exporte o acervo para usar como referência.');
const valid=E.validateCatalog(data.skills,catalog());for(const item of valid){const current=skill(item.id);if(current&&item.version<=current.version&&JSON.stringify(E.validateSkill(current))!==JSON.stringify(item))throw Error('A versão importada de '+item.id+' conflita com a atual. Revise e aumente a versão antes de importar.');}
pendingImport={kind:'catalog',value:valid};openDialog('Conferir importação do acervo',`<p>${valid.length} habilidade(s) serão adicionadas ou atualizadas pela identificação. Os registros de estudantes e os enunciados já aplicados serão preservados.</p><div class="actions">${button('Cancelar','close-dialog','secondary')}${button('Confirmar importação do acervo','confirm-import')}</div>`);}}
catch(error){announce(error.message||'Não foi possível ler o arquivo.',true);}
});
